#!/bin/sh
# Prepares the bundled stroke data, which is generated and not committed (tools/DATA_PROVENANCE.md):
#
#   1. the canonical source corpus tools/fixtures/source-data.json.gz, downloaded from its pinned
#      release asset and checked against SHA-256 (skipped when the local copy already matches);
#   2. the HZB1 packs in bundled-data/src/{android,jvm,ios,web}Main/resources/strokes, generated by
#      tools/generate_stroke_data.py (skipped when they were generated from this corpus; --force
#      regenerates them).
#
# Needs Python 3.14 and Node 22 (for its built-in Brotli encoder).
set -eu
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
SOURCE="$ROOT/tools/fixtures/source-data.json.gz"
SOURCE_URL="https://github.com/carr-engineering/shenzhen-hanzi-animator-kmp/releases/download/stroke-source-d6db1e36/source-data.json.gz"
SOURCE_SHA256="04d7c735a9ebd3273915bbfd7798924643ad81c3f47991b9dd0fe3e0f64268f1"
DECODED_SHA256="d6db1e36007c41b2d68132975bfc132a64f50b9ceae4254730918ba8ea3d5ced"

sha256() { shasum -a 256 "$1" | cut -d' ' -f1; }

if [ ! -f "$SOURCE" ] || [ "$(sha256 "$SOURCE")" != "$SOURCE_SHA256" ]; then
  curl -fsSL --retry 3 -o "$SOURCE.download" "$SOURCE_URL"
  actual="$(sha256 "$SOURCE.download")"
  [ "$actual" = "$SOURCE_SHA256" ] || { rm -f "$SOURCE.download"; echo "SHA-256 mismatch for $SOURCE_URL: $actual" >&2; exit 1; }
  mv "$SOURCE.download" "$SOURCE"
  echo "source corpus downloaded"
fi

# Each profile's manifest.json records the SHA-256 of the corpus it was generated from.
current=1
for target in androidMain jvmMain iosMain webMain; do
  grep -q "$DECODED_SHA256" "$ROOT/bundled-data/src/$target/resources/strokes/manifest.json" 2>/dev/null || current=0
done
if [ "${1:-}" = "--force" ] || [ "$current" = 0 ]; then
  python3 "$ROOT/tools/generate_stroke_data.py"
else
  echo "stroke packs are up to date"
fi
